                                           CanonicalTypeIndex type_index,
                                           int expected_arity,
                                           Suspend suspend) const {
  base::SpinningMutexGuard lock(&mutex_);
  auto it = entry_map_.find({kind, type_index, expected_arity, suspend});
  if (it == entry_map_.end()) return nullptr;
